const item = $input.first().json;
const body = item.body && typeof item.body === 'object' ? item.body : item;
const memo_id = String(body.memo_id || body.id || 'memo-unknown');
const payload = { memo_id, ts: new Date().toISOString(), note: body.note || '' };
const jwt = String($env.IPFS_API_KEY || '').trim();
let ipfs = {
  skipped: true,
  reason: 'IPFS_API_KEY vacío (JWT Pinata v3 en Bearer; ver docs Pinata)',
};
if (jwt) {
  try {
    const r = await fetch('https://api.pinata.cloud/pinning/pinJSONToIPFS', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: 'Bearer ' + jwt,
      },
      body: JSON.stringify({
        pinataContent: payload,
        pinataMetadata: { name: 'investment_memo_' + memo_id },
      }),
    });
    const t = await r.text();
    let parsed;
    try {
      parsed = JSON.parse(t);
    } catch {
      parsed = { raw: t };
    }
    ipfs = { http_status: r.status, response: parsed };
  } catch (e) {
    ipfs = { error: e.message };
  }
}
const ipfs_hash = ipfs.response?.IpfsHash || null;
let gaia = { skipped: true };
const gurl = String($env.N8N_GAIACHAIN_API || '').trim();
const gkey = String($env.N8N_GAIACHAIN_API_KEY || '').trim();
if (gurl && gkey && ipfs_hash) {
  try {
    const r = await fetch(gurl.replace(/\/$/, ''), {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: 'Bearer ' + gkey,
      },
      body: JSON.stringify({ ipfs_hash, memo_id, ts: payload.ts }),
    });
    gaia = { http_status: r.status, text: await r.text() };
  } catch (e) {
    gaia = { error: e.message };
  }
}
return [{ json: { memo_id, payload, ipfs, ipfs_hash, gaia } }];
